#!/usr/bin/env python3
"""Build assets/dashboard.svg from live GitHub data. Standard library only.

Usage: GH_TOKEN=... python3 scripts/generate_dashboard.py
"""
import base64
import json
import math
import os
import pathlib
import urllib.request
from collections import Counter, OrderedDict
from datetime import date
from html import escape

LOGIN = "mfarahat19"
ROLE = "Flutter Developer"
TAGLINE = "Scalable, maintainable, production-ready mobile apps."
OUTPUT = pathlib.Path(__file__).resolve().parent.parent / "assets" / "dashboard.svg"

# Generated by `flutter create`, so they say nothing about what was written by hand.
IGNORED_LANGUAGES = {"C", "C++", "CMake", "HTML", "Kotlin", "Objective-C", "Ruby", "Swift"}

FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif"
BG, PANEL, BORDER = "#0d1117", "#161b22", "#30363d"
TEXT, MUTED = "#f0f6fc", "#9da7b3"
ACCENT = "#3fb950"
HEAT = ["#21262d", "#0e4429", "#006d32", "#26a641", "#39d353"]
LANG_COLORS = ["#3b8eea", "#c4861c", "#c45f8c", "#2ea043"]
OTHER_COLOR = "#8b949e"

# GitHub shows this SVG through <img>, where CSS animation runs but scripts do not.
STYLE = """<style>
@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@keyframes grow{from{transform:scaleY(0)}to{transform:scaleY(1)}}
@keyframes draw{from{stroke-dashoffset:364.42}to{stroke-dashoffset:0}}
@keyframes pop{from{opacity:0;transform:scale(.3)}to{opacity:1;transform:scale(1)}}
@keyframes wave{0%,7%,100%{transform:scale(1)}3.5%{transform:scale(1.35)}}
@keyframes halo{0%{opacity:.7;transform:scale(1)}70%,100%{opacity:0;transform:scale(1.18)}}
.rise{animation:rise .6s ease-out both}
.bar{transform-box:fill-box;transform-origin:bottom;animation:grow .7s cubic-bezier(.2,.8,.2,1) both}
.draw{animation:draw 1.2s cubic-bezier(.4,0,.2,1) .3s both}
.cell,.active,.halo{transform-box:fill-box;transform-origin:center}
.cell{animation:pop .35s ease-out both}
.active{animation:pop .35s ease-out both,wave 7s ease-in-out infinite}
.halo{animation:halo 3.5s ease-out infinite}
@media (prefers-reduced-motion:reduce){*{animation:none!important}}
</style>"""

QUERY = """
query($login: String!) {
  user(login: $login) {
    name
    avatarUrl(size: 176)
    repositories(ownerAffiliations: OWNER, isFork: false, privacy: PUBLIC, first: 100) {
      totalCount
      nodes {
        name
        languages(first: 10, orderBy: {field: SIZE, direction: DESC}) {
          edges { size node { name } }
        }
      }
    }
    contributionsCollection {
      contributionCalendar {
        totalContributions
        weeks { contributionDays { date contributionCount weekday } }
      }
    }
  }
}
"""


def fetch():
    request = urllib.request.Request(
        "https://api.github.com/graphql",
        data=json.dumps({"query": QUERY, "variables": {"login": LOGIN}}).encode(),
        headers={"Authorization": f"bearer {os.environ['GH_TOKEN']}", "User-Agent": "profile-dashboard"},
    )
    with urllib.request.urlopen(request, timeout=30) as response:
        payload = json.load(response)
    if payload.get("errors"):
        raise SystemExit(payload["errors"])
    return payload["data"]["user"]


def avatar_data_uri(url):
    # Embedded because images inside an SVG shown through <img> cannot load remote files.
    request = urllib.request.Request(url, headers={"User-Agent": "profile-dashboard"})
    with urllib.request.urlopen(request, timeout=30) as response:
        mime = response.headers.get_content_type()
        return f"data:{mime};base64,{base64.b64encode(response.read()).decode()}"


def language_shares(repositories):
    totals = Counter()
    for repo in repositories:
        if repo["name"] == LOGIN:  # This profile repo only holds the dashboard generator.
            continue
        for edge in repo["languages"]["edges"]:
            if edge["node"]["name"] not in IGNORED_LANGUAGES:
                totals[edge["node"]["name"]] += edge["size"]
    grand_total = sum(totals.values()) or 1
    ranked = totals.most_common()
    shares = [(name, size / grand_total) for name, size in ranked[:4]]
    rest = sum(size for _, size in ranked[4:])
    if rest:
        shares.append(("Other", rest / grand_total))
    return shares


def longest_streak(days):
    best = current = 0
    for day in days:
        current = current + 1 if day["contributionCount"] else 0
        best = max(best, current)
    return best


def monthly_totals(days):
    totals = OrderedDict()
    for day in days:
        totals[day["date"][:7]] = totals.get(day["date"][:7], 0) + day["contributionCount"]
    return list(totals.items())[-12:]


def text(x, y, value, size=13, fill=TEXT, weight=400, anchor="start", spacing=0):
    extra = f' letter-spacing="{spacing}"' if spacing else ""
    return (
        f'<text x="{x:.1f}" y="{y:.1f}" font-size="{size}" fill="{fill}" font-weight="{weight}" '
        f'text-anchor="{anchor}"{extra}>{escape(str(value))}</text>'
    )


def panel(x, y, w, h):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{PANEL}" stroke="{BORDER}"/>'


def panel_title(x, y, value):
    return text(x, y, value.upper(), 12, MUTED, 600, spacing=1.2)


def month_chart(months, x, y, w, h):
    parts = [panel(x, y, w, h), panel_title(x + 20, y + 30, "Contributions by month")]
    peak = max((count for _, count in months), default=0) or 1
    baseline, max_height = y + h - 38, h - 96
    step, bar_w = (w - 40) / max(len(months), 1), 14
    parts.append(
        f'<line x1="{x + 20}" y1="{baseline + .5}" x2="{x + w - 20}" y2="{baseline + .5}" stroke="{BORDER}"/>'
    )
    peak_labelled = False
    for index, (key, count) in enumerate(months):
        cx = x + 20 + step * (index + 0.5)
        label = date(int(key[:4]), int(key[5:]), 1).strftime("%b")
        parts.append(text(cx, baseline + 20, label, 11, MUTED, anchor="middle"))
        if count:
            height = max(4, count / peak * max_height)
            left, top, right = cx - bar_w / 2, baseline - height, cx + bar_w / 2
            parts.append(
                f'<path d="M{left:.1f} {baseline} V{top + 4:.1f} Q{left:.1f} {top:.1f} {left + 4:.1f} {top:.1f} '
                f'H{right - 4:.1f} Q{right:.1f} {top:.1f} {right:.1f} {top + 4:.1f} V{baseline} Z" fill="{ACCENT}" '
                f'class="bar" style="animation-delay:{0.2 + index * 0.05:.2f}s"/>'
            )
        if count == peak and not peak_labelled:
            label_svg = text(cx, baseline - count / peak * max_height - 8, count, 12, TEXT, 600, "middle")
            parts.append(f'<g class="rise" style="animation-delay:1s">{label_svg}</g>')
            peak_labelled = True
    return "".join(parts)


def language_chart(shares, x, y, w, h):
    parts = [panel(x, y, w, h), panel_title(x + 20, y + 30, "Language mix")]
    cx, cy, radius, stroke = x + 96, y + 122, 58, 20
    circumference = 2 * math.pi * radius
    colors = []
    color_index = 0
    for name, _ in shares:
        if name == "Other":
            colors.append(OTHER_COLOR)
        else:
            colors.append(LANG_COLORS[color_index])
            color_index += 1
    gap = 2 if len(shares) > 1 else 0
    offset = 0.0
    parts.append(
        f'<mask id="donut-reveal" maskUnits="userSpaceOnUse" x="{x}" y="{y}" width="{w}" height="{h}">'
        f'<circle class="draw" cx="{cx}" cy="{cy}" r="{radius}" fill="none" stroke="#fff" stroke-width="{stroke + 2}" '
        f'stroke-dasharray="{circumference:.2f}" transform="rotate(-90 {cx} {cy})"/></mask><g mask="url(#donut-reveal)">'
    )
    for (_, share), color in zip(shares, colors):
        length = share * circumference
        parts.append(
            f'<circle cx="{cx}" cy="{cy}" r="{radius}" fill="none" stroke="{color}" stroke-width="{stroke}" '
            f'stroke-dasharray="{max(length - gap, 0.5):.2f} {circumference:.2f}" stroke-dashoffset="{-offset:.2f}" '
            f'transform="rotate(-90 {cx} {cy})"/>'
        )
        offset += length
    parts.append("</g>")
    if shares:
        parts.append(text(cx, cy + 3, f"{shares[0][1] * 100:.0f}%", 20, TEXT, 700, "middle"))
        parts.append(text(cx, cy + 20, shares[0][0], 12, MUTED, anchor="middle"))
    legend_x, row_y = x + 196, cy - (len(shares) - 1) * 14
    for (name, share), color in zip(shares, colors):
        parts.append(f'<rect x="{legend_x}" y="{row_y - 9:.1f}" width="10" height="10" rx="3" fill="{color}"/>')
        parts.append(text(legend_x + 18, row_y, name, 13))
        label = f"{share * 100:.0f}%" if share >= 0.005 else "<1%"
        parts.append(text(x + w - 20, row_y, label, 13, MUTED, anchor="end"))
        row_y += 28
    return "".join(parts)


def heat_levels(days):
    counts = sorted(day["contributionCount"] for day in days if day["contributionCount"])
    if not counts:
        return [0, 0, 0]
    return [counts[len(counts) * q // 4] for q in (1, 2, 3)]


def heat_level(count, cuts):
    if not count:
        return 0
    return 1 + sum(count > cut for cut in cuts)


def heatmap(weeks, x, y, w, h):
    parts = [panel(x, y, w, h), panel_title(x + 20, y + 30, "Contribution calendar")]
    cell, step = 11, 14
    weeks = weeks[-53:]
    grid_x, grid_y = x + 54, y + 62
    cuts = heat_levels([day for week in weeks for day in week["contributionDays"]])
    for row, label in ((1, "Mon"), (3, "Wed"), (5, "Fri")):
        parts.append(text(x + 20, grid_y + row * step + 10, label, 11, MUTED))
    previous_month = None
    for column, week in enumerate(weeks):
        days = week["contributionDays"]
        month = days[0]["date"][:7]
        # Skip a label for a first column that holds only the tail of a month.
        if month != previous_month and (previous_month or days[0]["date"][8:] <= "07"):
            if column < len(weeks) - 2:
                label = date(int(month[:4]), int(month[5:]), 1).strftime("%b")
                parts.append(text(grid_x + column * step, y + 54, label, 11, MUTED))
        previous_month = month
        for day in days:
            fill = HEAT[heat_level(day["contributionCount"], cuts)]
            pop_delay = 0.3 + column * 0.018 + day["weekday"] * 0.012
            if day["contributionCount"]:
                # Same period, later start per column: the pulse travels left to right.
                motion = f'class="active" style="animation-delay:{pop_delay:.2f}s,{2.2 + column * 0.05:.2f}s"'
            else:
                motion = f'class="cell" style="animation-delay:{pop_delay:.2f}s"'
            parts.append(
                f'<rect x="{grid_x + column * step}" y="{grid_y + day["weekday"] * step}" '
                f'width="{cell}" height="{cell}" rx="2.5" fill="{fill}" {motion}/>'
            )
    legend_x = x + w - 20 - len(HEAT) * step - 30
    parts.append(text(legend_x - 8, y + 30, "Less", 11, MUTED, anchor="end"))
    for index, fill in enumerate(HEAT):
        parts.append(
            f'<rect x="{legend_x + index * step}" y="{y + 20}" width="{cell}" height="{cell}" rx="2.5" fill="{fill}"/>'
        )
    parts.append(text(legend_x + len(HEAT) * step + 4, y + 30, "More", 11, MUTED))
    return "".join(parts)


def render(user):
    calendar = user["contributionsCollection"]["contributionCalendar"]
    days = [day for week in calendar["weeks"] for day in week["contributionDays"]]
    stats = [
        (f'{calendar["totalContributions"]:,}', "Contributions / year"),
        (user["repositories"]["totalCount"], "Public repos"),
        (sum(1 for day in days if day["contributionCount"]), "Active days"),
        (f"{longest_streak(days)} days", "Longest streak"),
    ]
    width, height = 860, 678
    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" width="{width}" height="{height}" '
        f'font-family="{FONT}" role="img" aria-label="GitHub dashboard for {escape(user["name"])}">',
        STYLE,
        '<defs><clipPath id="avatar"><circle cx="72" cy="78" r="44"/></clipPath>',
        f'<radialGradient id="glow" cx="0" cy="0" r="1"><stop offset="0" stop-color="{ACCENT}" stop-opacity=".16"/>'
        f'<stop offset="1" stop-color="{ACCENT}" stop-opacity="0"/></radialGradient></defs>',
        f'<rect x=".5" y=".5" width="{width - 1}" height="{height - 1}" rx="18" fill="{BG}" stroke="{BORDER}"/>',
        '<rect x="1" y="1" width="520" height="240" rx="18" fill="url(#glow)"/>',
        f'<image href="{avatar_data_uri(user["avatarUrl"])}" x="28" y="34" width="88" height="88" clip-path="url(#avatar)"/>',
        f'<circle class="halo" cx="72" cy="78" r="46" fill="none" stroke="{ACCENT}" stroke-width="2"/>',
        f'<circle cx="72" cy="78" r="46" fill="none" stroke="{ACCENT}" stroke-width="2"/>',
        text(140, 66, user["name"], 32, TEXT, 700),
        text(140, 93, f"@{LOGIN}  ·  {ROLE}", 15, ACCENT, 600),
        text(140, 117, TAGLINE, 14, MUTED),
    ]
    tile_w, tile_gap = 191, 16
    for index, (value, label) in enumerate(stats):
        tile_x = 24 + index * (tile_w + tile_gap)
        parts.append(f'<g class="rise" style="animation-delay:{index * 0.1:.1f}s">')
        parts.append(panel(tile_x, 152, tile_w, 84))
        parts.append(text(tile_x + tile_w / 2, 192, value, 26, TEXT, 700, "middle"))
        parts.append(text(tile_x + tile_w / 2, 216, label.upper(), 11, MUTED, 600, "middle", 1))
        parts.append("</g>")
    parts.append(month_chart(monthly_totals(days), 24, 252, 398, 216))
    parts.append(language_chart(language_shares(user["repositories"]["nodes"]), 438, 252, 398, 216))
    parts.append(heatmap(calendar["weeks"], 24, 484, 812, 170))
    parts.append("</svg>")
    return "".join(parts)


if __name__ == "__main__":
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(render(fetch()), encoding="utf-8")
    print(f"Wrote {OUTPUT}")
